/* @catalog — generated by `npm run catalog:generate`; do not edit by hand.
 * Internal
 *   Types: AssetState, Reply, Seen
 *   Functions: readBlob, project, files, asset, serve, settle, header
 *   Constants: hashes, original
 * Tests
 *   - one approval sends one request per file in manifest order with the cover last, never two in flight
 *   - leaving Admin view mid-file stops after the current file, and navigation never restarts the queue
 *   - a 403 stops the queue and resets the private workspace
 *   - an unknown outcome is retried only by its starter, with its original key, If-Match and identical multipart bytes
 *   - cross-device recovery reconciles first, then resends the admitted key and revision, never a new intent
 *   - an exact match found by reconciliation needs no bytes
 *   - a definite refusal or a confirmed failure gets a new intent at the latest revision
 *   - a busy lease stays unknown for its own file while the queue continues with the next file
 *   - Resume after a lost response that was never admitted replays the original key, If-Match and identical bytes
 *   - a response lost after admission is found by the refresh, and Resume continues that admitted intent
 *   - an abort after the upload was sent keeps its outcome unknown under its intent and stops as permission
 *   - a discarded slot leaves the running queue and its remembered intent, and a later Resume cannot send it
 *   - reselection matches relative path and size, reports mismatches, and a changed file is refused without dispatching bytes
 *   - reopening reconciles unknown uploads with their original intent and no bytes, and skips while the queue runs
 *   - an outdated strict response requires a reload and stops the queue without retrying
 *   - the multipart body keeps a Unicode filename and a normalized media type for the server parser
 *   - a view change after reconciliation aborts the resend before dispatch and stops the queue as view
 *   - definite refusals fail or refuse only their own file while the queue continues, and each 409 refreshes the project once
 *   - a staged copy still being removed is refused without a request, and a receipt for another operation stays unknown
 *   - Resume while uploading adds nothing, and an explicit retry joins the running queue once
 *   - a publication lock met while reconciling keeps that upload unknown and stops before any bytes are sent
 *   - reopening stops reconciling at a permission failure and never retries later uploads
 *   - a Resume during reopen reconciliation waits for it and then sends only the files still incomplete
 * @end-catalog */

import { createRequire } from 'node:module';
import { captureAccountOperation } from '../../api/accountEpoch';
import type { ImportDetail } from './adminApi';
import { adminWorkspace } from './adminWorkspace';
import { importUploadQueue, importUploadRequest, type ImportUploadQueue } from './importUploadQueue';
import { matchReselection } from './importUploadRules';
import { deferred, detail, json, slotId, slotTwo, viewer } from './adminFixtures.testSupport';

const hashes = vi.hoisted(() => new Map<string, string>());
vi.mock('./conversionSourceValidation', () => ({ hashConversionFile: vi.fn(async (file: File) => hashes.get(file.name) ?? 'a'.repeat(64)) }));

type AssetState = ImportDetail['assets'][number]['state'];
/** `drop` loses the connection before or after the upload is admitted, as a lost response would. */
interface Reply { status?: number; code?: string; state?: AssetState; body?: (item: ImportDetail, operationId: string) => unknown; hold?: Promise<void>; drop?: 'before' | 'after' }
interface Seen { path: string; init: RequestInit; slot: string | null; reconcile: boolean }
const readBlob = (blob: Blob) => new Promise<string>((resolve, reject) => { const reader = new FileReader(); reader.onload = () => resolve(String(reader.result)); reader.onerror = reject; reader.readAsText(blob); });
const original = '30000000-0000-4000-8000-000000000003';
function project(): ImportDetail { const item = detail(); item.capabilities.upload = true; item.upload.available = true; item.publication = 'notStarted'; return item; }
const files = (): Record<string, File> => ({ [slotId]: new File(['a'.repeat(100)], '01 First.mp3'), [slotTwo]: new File(['b'.repeat(200)], '02 Second.mp3') });
const asset = (slot: string, state: AssetState, startedByMe = true, operationId = original): ImportDetail['assets'][number] => ({ slotId: slot, state, byteLength: slot === slotTwo ? 200 : 100, sha256: 'a'.repeat(64), contentType: 'audio/mpeg', tags: null, recovery: { operationId, expectedRevision: 2, kind: 'upload', startedByMe } });
/** A synthetic private import endpoint: each asset POST admits its intent and reports the scripted outcome. */
function serve(start: ImportDetail, reply: (seen: Seen, index: number) => Reply | undefined = () => undefined) {
  let item = structuredClone(start), active = 0, max = 0; const requests: Seen[] = [];
  vi.stubGlobal('fetch', vi.fn(async (path: string, init: RequestInit = {}) => {
    const match = /\/assets\/([^/]+?)(\/reconcile)?$/.exec(path), seen = { path, init, slot: match ? decodeURIComponent(match[1]) : null, reconcile: Boolean(match?.[2]) };
    requests.push(seen); active++; max = Math.max(max, active);
    try {
      await new Promise(resolve => setTimeout(resolve, 2));
      const custom = seen.slot ? reply(seen, requests.length - 1) : undefined; await custom?.hold;
      if (custom?.status) return json({ code: custom.code }, custom.status);
      if (seen.slot && seen.reconcile) {
        if (custom?.state) item = { ...item, revision: item.revision + 1, assets: item.assets.map(value => value.slotId === seen.slot ? { ...value, state: custom.state! } : value) };
        return json({ item, receipt: null });
      }
      if (seen.slot && init.method === 'POST') {
        if (custom?.drop === 'before') throw new TypeError('Failed to fetch');
        const headers = new Headers(init.headers), operationId = headers.get('Idempotency-Key')!, slot = seen.slot;
        const recovery = { operationId, expectedRevision: Number(headers.get('If-Match')), kind: 'upload' as const, startedByMe: true };
        item = { ...item, revision: item.revision + 1, assets: [...item.assets.filter(value => value.slotId !== slot), { ...asset(slot, custom?.state ?? 'ready'), recovery }] };
        if (custom?.drop === 'after') throw new TypeError('Failed to fetch');
        return json(custom?.body ? custom.body(item, operationId) : { item, receipt: { operationId, kind: 'upload', revision: item.revision } });
      }
      return json({ item, receipt: null });
    } finally { active--; }
  }));
  return { requests, uploads: () => requests.filter(request => request.slot && !request.reconcile), max: () => max, item: () => item };
}
const settle = (queue: ImportUploadQueue) => vi.waitFor(() => expect(queue.getSnapshot().running).toBe(false));
const header = (request: Seen, name: string) => new Headers(request.init.headers).get(name);

beforeEach(() => { hashes.clear(); adminWorkspace.reset(); adminWorkspace.authorize(captureAccountOperation(viewer), true, true); adminWorkspace.select('admin'); });
afterEach(() => { adminWorkspace.reset(); vi.unstubAllGlobals(); });

test('one approval sends one request per file in manifest order with the cover last, never two in flight', async () => {
  const item = project(), server = serve(item), queue = importUploadQueue(item.id);
  queue.start(item, { cover: new File(['png'], 'cover.png'), ...files() }, adminWorkspace.capture()); await settle(queue);
  expect(server.uploads().map(request => request.slot)).toEqual([slotId, slotTwo, 'cover']); expect(server.max()).toBe(1);
  expect(Object.values(queue.getSnapshot().files).map(value => value.state)).toEqual(['ready', 'ready', 'ready']);
  // Each new intent carries the newest observed revision as its If-Match fingerprint.
  expect(server.uploads().map(request => header(request, 'If-Match'))).toEqual(['1', '2', '3']);
  expect(new Set(server.uploads().map(request => header(request, 'Idempotency-Key'))).size).toBe(3);
  expect(queue.getSnapshot().latest?.revision).toBe(4); expect(queue.getSnapshot().stopped).toBeNull();
});

test('leaving Admin view mid-file stops after the current file, and navigation never restarts the queue', async () => {
  const item = project(), gate = deferred<void>(), server = serve(item, (_seen, index) => index === 0 ? { hold: gate.promise } : undefined), queue = importUploadQueue(item.id);
  queue.start(item, files(), adminWorkspace.capture()); await vi.waitFor(() => expect(server.requests).toHaveLength(1));
  adminWorkspace.select('user'); gate.resolve(); await settle(queue);
  expect(server.requests).toHaveLength(1); expect(queue.getSnapshot().stopped).toBe('view');
  expect(queue.getSnapshot().files[slotId].state).toBe('ready'); expect(queue.getSnapshot().files[slotTwo].state).toBe('stopped');
  adminWorkspace.select('admin'); await new Promise(resolve => setTimeout(resolve, 20));
  expect(importUploadQueue(item.id)).toBe(queue); expect(queue.getSnapshot().running).toBe(false); expect(server.requests).toHaveLength(1);
  queue.start(queue.getSnapshot().latest!, files(), adminWorkspace.capture()); await settle(queue);
  expect(server.uploads().map(request => request.slot)).toEqual([slotId, slotTwo]);
});

test('a 403 stops the queue and resets the private workspace', async () => {
  const item = project(), server = serve(item, () => ({ status: 403, code: 'ADMIN_IMPORT_ADMIN_REQUIRED' })), queue = importUploadQueue(item.id);
  queue.start(item, files(), adminWorkspace.capture()); await settle(queue);
  expect(server.requests).toHaveLength(1); expect(queue.getSnapshot().stopped).toBe('permission');
  expect(queue.getSnapshot().files[slotId].state).toBe('unknown'); expect(queue.getSnapshot().files[slotTwo].state).toBe('stopped');
  expect(adminWorkspace.getSnapshot().authorized).toBe(false); expect(adminWorkspace.buffer(`upload-queue:${item.id}`)).toBeUndefined();
});

test.each(['refusal', 'locked item'] as const)('a publication lock (%s) stops the queue after the current file', async variant => {
  const item = project(), server = serve(item, () => variant === 'refusal' ? { status: 409, code: 'ADMIN_IMPORT_PUBLICATION_LOCKED' }
    : { body: (next, operationId) => ({ item: { ...next, publication: 'preparing', publicationRecovery: { operationId: original, cleanupPending: false, startedByMe: false } }, receipt: { operationId, kind: 'upload', revision: next.revision } }) });
  const queue = importUploadQueue(item.id); queue.start(item, files(), adminWorkspace.capture()); await settle(queue);
  expect(server.uploads()).toHaveLength(1); expect(queue.getSnapshot().stopped).toBe('publication');
  expect(queue.getSnapshot().files[slotId].state).toBe(variant === 'refusal' ? 'failed' : 'ready'); expect(queue.getSnapshot().files[slotTwo].state).toBe('stopped');
  // A 409 refreshes the project once so the rows show the server state.
  expect(server.requests.filter(request => !request.slot)).toHaveLength(variant === 'refusal' ? 1 : 0);
});

test('an unknown outcome is retried only by its starter, with its original key, If-Match and identical multipart bytes', async () => {
  const item = project(), server = serve(item, (_seen, index) => index === 0 ? { state: 'unknown' } : undefined), queue = importUploadQueue(item.id), source = files();
  queue.start(item, { [slotId]: source[slotId] }, adminWorkspace.capture()); await settle(queue);
  expect(queue.getSnapshot().files[slotId].state).toBe('unknown');
  queue.enqueue(slotId, source[slotId], queue.getSnapshot().latest!, adminWorkspace.capture()); await settle(queue);
  const [first, check, second] = server.requests;
  expect(check.reconcile).toBe(true); expect(JSON.parse(String(check.init.body))).toEqual({ operationId: header(first, 'Idempotency-Key') }); expect(header(check, 'Idempotency-Key')).toBeNull();
  expect(header(second, 'Idempotency-Key')).toBe(header(first, 'Idempotency-Key')); expect(header(second, 'If-Match')).toBe('1');
  expect(await readBlob(second.init.body as Blob)).toBe(await readBlob(first.init.body as Blob)); expect(queue.getSnapshot().files[slotId].state).toBe('ready');
  const other = project(); other.id = 'eeeeeeeeeeeeeeeeeeeeeeee'; other.assets = [asset(slotId, 'unknown', false)];
  const foreignServer = serve(other), foreign = importUploadQueue(other.id); foreign.start(other, source, adminWorkspace.capture()); await settle(foreign);
  expect(foreign.getSnapshot().files[slotId]).toEqual({ state: 'unknown', code: 'other_owner', operationId: original });
  expect(foreignServer.requests.filter(request => request.slot === slotId)).toHaveLength(0);
});

test('cross-device recovery reconciles first, then resends the admitted key and revision, never a new intent', async () => {
  const item = project(); item.assets = [asset(slotId, 'pending')]; const server = serve(item), queue = importUploadQueue(item.id);
  queue.start(item, files(), adminWorkspace.capture()); await settle(queue);
  const [check, retry] = server.requests;
  expect(check.reconcile).toBe(true); expect(header(retry, 'Idempotency-Key')).toBe(original); expect(header(retry, 'If-Match')).toBe('2');
  expect(queue.getSnapshot().files[slotId]).toEqual({ state: 'ready', code: null, operationId: original });
});

test('an exact match found by reconciliation needs no bytes', async () => {
  const item = project(); item.assets = [asset(slotId, 'unknown')]; const server = serve(item, seen => seen.reconcile ? { state: 'ready' } : undefined), queue = importUploadQueue(item.id);
  queue.start(item, { [slotId]: files()[slotId] }, adminWorkspace.capture()); await settle(queue);
  expect(server.requests).toHaveLength(1); expect(server.requests[0].reconcile).toBe(true); expect(queue.getSnapshot().files[slotId].state).toBe('ready');
});

test('a definite refusal or a confirmed failure gets a new intent at the latest revision', async () => {
  const item = project(), server = serve(item, (_seen, index) => index === 0 ? { status: 400, code: 'ADMIN_IMPORT_FILE_CHANGED' } : undefined), queue = importUploadQueue(item.id), source = files();
  queue.start(item, { [slotId]: source[slotId] }, adminWorkspace.capture()); await settle(queue);
  expect(queue.getSnapshot().files[slotId]).toMatchObject({ state: 'refused', code: 'file_changed' });
  queue.enqueue(slotId, source[slotId], queue.getSnapshot().latest!, adminWorkspace.capture()); await settle(queue);
  expect(header(server.requests[1], 'Idempotency-Key')).not.toBe(header(server.requests[0], 'Idempotency-Key'));
  const failed = project(); failed.id = 'eeeeeeeeeeeeeeeeeeeeeeee'; failed.revision = 5; failed.assets = [asset(slotId, 'failed', false)];
  const next = serve(failed), replacement = importUploadQueue(failed.id); replacement.start(failed, { [slotId]: source[slotId] }, adminWorkspace.capture()); await settle(replacement);
  const [check, upload] = next.requests;
  expect(check.reconcile).toBe(true); expect(header(upload, 'Idempotency-Key')).not.toBe(original); expect(header(upload, 'If-Match')).toBe('5');
  expect(replacement.getSnapshot().files[slotId].state).toBe('ready');
});

test.each([[409, 'ADMIN_IMPORT_OPERATION_LIMIT', 'limit'], [503, 'ADMIN_IMPORT_STORAGE_UNAVAILABLE', 'unavailable']] as const)('a %s %s refusal fails the file and stops as %s', async (status, code, reason) => {
  const item = project(), server = serve(item, () => ({ status, code })), queue = importUploadQueue(item.id);
  queue.start(item, files(), adminWorkspace.capture()); await settle(queue);
  expect(server.uploads()).toHaveLength(1); expect(queue.getSnapshot().files[slotId]).toMatchObject({ state: 'failed', code }); expect(queue.getSnapshot().stopped).toBe(reason);
});

test('a busy lease stays unknown for its own file while the queue continues with the next file', async () => {
  const item = project(), server = serve(item, seen => seen.slot === slotId ? { status: 409, code: 'ADMIN_IMPORT_ASSET_BUSY' } : undefined), queue = importUploadQueue(item.id);
  queue.start(item, { ...files(), cover: new File(['png'], 'cover.png') }, adminWorkspace.capture()); await settle(queue);
  expect(server.uploads().map(request => request.slot)).toEqual([slotId, slotTwo, 'cover']);
  expect([slotId, slotTwo, 'cover'].map(slot => queue.getSnapshot().files[slot].state)).toEqual(['unknown', 'ready', 'ready']); expect(queue.getSnapshot().stopped).toBeNull();
});

test.each([['a lost response', { drop: 'before' }], ['a server failure', { status: 503, code: 'ADMIN_IMPORT_UNAVAILABLE' }]] as const)('%s refreshes the project and stops the queue after that file', async (_name, failure) => {
  const item = project(), server = serve(item, seen => seen.slot === slotId ? failure : undefined), queue = importUploadQueue(item.id);
  queue.start(item, files(), adminWorkspace.capture()); await settle(queue);
  expect(server.uploads().map(request => request.slot)).toEqual([slotId]); expect(server.requests.filter(request => !request.slot)).toHaveLength(1);
  expect(queue.getSnapshot().stopped).toBe('interrupted');
  expect(queue.getSnapshot().files[slotId]).toMatchObject({ state: 'unknown', operationId: header(server.uploads()[0], 'Idempotency-Key') }); expect(queue.getSnapshot().files[slotTwo].state).toBe('stopped');
});

test('Resume after a lost response that was never admitted replays the original key, If-Match and identical bytes', async () => {
  const item = project(), server = serve(item, (_seen, index) => index === 0 ? { drop: 'before' } : undefined), queue = importUploadQueue(item.id), source = files();
  queue.start(item, source, adminWorkspace.capture()); await settle(queue);
  expect(queue.getSnapshot().latest?.assets).toEqual([]);
  queue.start(queue.getSnapshot().latest!, source, adminWorkspace.capture()); await settle(queue);
  const [first, replay, second] = server.uploads();
  expect([first.slot, replay.slot, second.slot]).toEqual([slotId, slotId, slotTwo]);
  expect(header(replay, 'Idempotency-Key')).toBe(header(first, 'Idempotency-Key')); expect(header(replay, 'If-Match')).toBe(header(first, 'If-Match'));
  expect(await readBlob(replay.init.body as Blob)).toBe(await readBlob(first.init.body as Blob));
  // Before choosing an intent, the replay reads the project once more in case the earlier request was admitted unseen.
  expect(server.requests.map(request => request.slot ? 'upload' : 'read')).toEqual(['upload', 'read', 'read', 'upload', 'upload']);
  expect(queue.getSnapshot().files[slotId]).toEqual({ state: 'ready', code: null, operationId: header(first, 'Idempotency-Key') }); expect(queue.getSnapshot().stopped).toBeNull();
});

test('a response lost after admission is found by the refresh, and Resume continues that admitted intent', async () => {
  const item = project(), server = serve(item, (_seen, index) => index === 0 ? { drop: 'after', state: 'unknown' } : undefined), queue = importUploadQueue(item.id), source = files();
  queue.start(item, { [slotId]: source[slotId] }, adminWorkspace.capture()); await settle(queue);
  const key = header(server.uploads()[0], 'Idempotency-Key');
  expect(queue.getSnapshot().latest?.assets.map(value => [value.slotId, value.state, value.recovery?.operationId])).toEqual([[slotId, 'unknown', key]]);
  queue.start(queue.getSnapshot().latest!, { [slotId]: source[slotId] }, adminWorkspace.capture()); await settle(queue);
  expect(server.requests.map(request => request.reconcile ? 'reconcile' : request.slot ? 'upload' : 'read')).toEqual(['upload', 'read', 'reconcile', 'upload']);
  expect(server.uploads().map(request => header(request, 'Idempotency-Key'))).toEqual([key, key]); expect(queue.getSnapshot().files[slotId].state).toBe('ready');
});

test('an abort after the upload was sent keeps its outcome unknown under its intent and stops as permission', async () => {
  const item = project(), gate = deferred<void>(), server = serve(item, (_seen, index) => index === 0 ? { hold: gate.promise } : undefined), queue = importUploadQueue(item.id);
  queue.start(item, files(), adminWorkspace.capture()); await vi.waitFor(() => expect(server.requests).toHaveLength(1));
  // A new authority invalidates the admitted write's guard after dispatch, so the transport aborts on the response.
  adminWorkspace.reset(); gate.resolve(); await settle(queue);
  expect(server.uploads()).toHaveLength(1); expect(queue.getSnapshot().stopped).toBe('permission');
  expect(queue.getSnapshot().files[slotId]).toEqual({ state: 'unknown', code: null, operationId: header(server.uploads()[0], 'Idempotency-Key') });
  expect(queue.getSnapshot().files[slotTwo].state).toBe('stopped');
});

test('a discarded slot leaves the running queue and its remembered intent, and a later Resume cannot send it', async () => {
  const item = project(), gate = deferred<void>(), server = serve(item, (_seen, index) => index === 0 ? { hold: gate.promise } : undefined), queue = importUploadQueue(item.id);
  const source = { ...files(), cover: new File(['png'], 'cover.png') };
  queue.start(item, source, adminWorkspace.capture()); await vi.waitFor(() => expect(server.requests).toHaveLength(1));
  queue.discard('cover'); expect(queue.getSnapshot().files.cover).toBeUndefined();
  gate.resolve(); await settle(queue);
  expect(server.uploads().map(request => request.slot)).toEqual([slotId, slotTwo]);
  const { cover: _removed, ...kept } = source; queue.start(queue.getSnapshot().latest!, kept, adminWorkspace.capture()); await settle(queue);
  expect(server.uploads().map(request => request.slot)).toEqual([slotId, slotTwo]);
});

test('reselection matches relative path and size, reports mismatches, and a changed file is refused without dispatching bytes', async () => {
  const item = project(); item.assets = [asset(slotTwo, 'ready')];
  const pick = (name: string, size: number, path?: string) => { const file = new File(['x'.repeat(size)], name); if (path) Object.defineProperty(file, 'webkitRelativePath', { value: path }); return file; };
  const first = pick('01 First.mp3', 100, 'Synthetic Album/01 First.mp3');
  expect(matchReselection(item, [first, pick('02 Second.mp3', 200, 'Synthetic Album/02 Second.mp3'), pick('01 First.mp3', 100), pick('notes.txt', 3, 'Synthetic Album/notes.txt')]))
    .toEqual({ matched: { [slotId]: first }, mismatched: ['01 First.mp3'] });
  expect(matchReselection(item, [pick('01 First.mp3', 99, 'Synthetic Album/01 First.mp3')])).toEqual({ matched: {}, mismatched: ['Synthetic Album/01 First.mp3'] });
  item.assets = [asset(slotId, 'unknown')]; hashes.set('01 First.mp3', 'c'.repeat(64));
  const server = serve(item), queue = importUploadQueue(item.id); queue.start(item, { [slotId]: first }, adminWorkspace.capture()); await settle(queue);
  expect(server.requests.map(request => request.reconcile)).toEqual([true]); expect(queue.getSnapshot().files[slotId]).toMatchObject({ state: 'refused', code: 'content_changed' });
});

test('reopening reconciles unknown uploads with their original intent and no bytes, and skips while the queue runs', async () => {
  const item = project(); item.assets = [asset(slotId, 'unknown', false), asset(slotTwo, 'pending', true, '40000000-0000-4000-8000-000000000004')];
  const server = serve(item), queue = importUploadQueue(item.id);
  await queue.reconcileOnOpen(item, adminWorkspace.capture());
  expect(server.requests.map(request => [request.slot, request.reconcile, JSON.parse(String(request.init.body))])).toEqual([[slotId, true, { operationId: original }], [slotTwo, true, { operationId: '40000000-0000-4000-8000-000000000004' }]]);
  expect(server.requests.every(request => typeof request.init.body === 'string' && !header(request, 'Idempotency-Key'))).toBe(true);
  const gate = deferred<void>(), busy = project(); busy.id = 'eeeeeeeeeeeeeeeeeeeeeeee'; const held = serve(busy, () => ({ hold: gate.promise })), running = importUploadQueue(busy.id);
  running.start(busy, files(), adminWorkspace.capture()); await vi.waitFor(() => expect(held.requests).toHaveLength(1));
  await running.reconcileOnOpen({ ...busy, assets: [asset(slotTwo, 'unknown')] }, adminWorkspace.capture());
  expect(held.requests.some(request => request.reconcile)).toBe(false); gate.resolve(); await settle(running);
});

test('an outdated strict response requires a reload and stops the queue without retrying', async () => {
  const item = project(), server = serve(item, () => ({ body: (next, operationId) => ({ item: { ...next, futureField: true }, receipt: { operationId, kind: 'upload', revision: next.revision } }) })), queue = importUploadQueue(item.id);
  queue.start(item, files(), adminWorkspace.capture()); await settle(queue);
  expect(server.requests).toHaveLength(1); expect(queue.getSnapshot().stopped).toBe('reload'); expect(adminWorkspace.getSnapshot().reloadRequired).toBe(true);
  expect(queue.getSnapshot().files[slotId].state).toBe('unknown'); expect(queue.getSnapshot().files[slotTwo].state).toBe('stopped');
});

test('the multipart body keeps a Unicode filename and a normalized media type for the server parser', async () => {
  const { headers, body } = importUploadRequest(new File(['abc'], '音乐.mp3', { type: 'untrusted/type' }), original, 3);
  expect(headers).toMatchObject({ 'Idempotency-Key': original, 'If-Match': '3' });
  const multipart = await readBlob(body); expect(multipart).toContain('Content-Type: audio/mpeg'); expect(multipart).toContain("filename*=UTF-8''%E9%9F%B3%E4%B9%90.mp3"); expect(multipart).toContain('\r\n\r\nabc\r\n');
  const busboy = createRequire(import.meta.url)('busboy')({ headers: { 'content-type': headers['Content-Type'] } });
  const parsed = new Promise<{ filename: string; mimeType: string }>(resolve => { busboy.on('file', (_field: string, stream: { resume: () => void }, info: { filename: string; mimeType: string }) => { stream.resume(); resolve(info); }); });
  busboy.end(Buffer.from(multipart)); expect(await parsed).toMatchObject({ filename: '音乐.mp3', mimeType: 'audio/mpeg' });
  expect(await readBlob(importUploadRequest(new File(['abc'], '音乐.mp3'), original, 3).body)).toBe(multipart);
});

test('a view change after reconciliation aborts the resend before dispatch and stops the queue as view', async () => {
  const item = project(); item.assets = [asset(slotId, 'unknown')]; const gate = deferred<void>();
  const server = serve(item, seen => seen.reconcile ? { hold: gate.promise } : undefined), queue = importUploadQueue(item.id);
  queue.start(item, files(), adminWorkspace.capture()); await vi.waitFor(() => expect(server.requests).toHaveLength(1));
  adminWorkspace.select('user'); gate.resolve(); await settle(queue);
  expect(server.requests.map(request => request.reconcile)).toEqual([true]); expect(queue.getSnapshot().stopped).toBe('view');
  expect(queue.getSnapshot().files).toEqual({ [slotId]: { state: 'stopped', code: null, operationId: null }, [slotTwo]: { state: 'stopped', code: null, operationId: null } });
});

test('definite refusals fail or refuse only their own file while the queue continues, and each 409 refreshes the project once', async () => {
  const codes: Record<string, [number, string]> = { [slotId]: [409, 'ADMIN_IMPORT_OPERATION_CONFLICT'], [slotTwo]: [404, 'ADMIN_IMPORT_NOT_FOUND'], cover: [409, 'ADMIN_IMPORT_ASSET_EXISTS'] };
  const item = project(), server = serve(item, seen => ({ status: codes[seen.slot!][0], code: codes[seen.slot!][1] })), queue = importUploadQueue(item.id);
  queue.start(item, { ...files(), cover: new File(['png'], 'cover.png') }, adminWorkspace.capture()); await settle(queue);
  expect(server.uploads().map(request => request.slot)).toEqual([slotId, slotTwo, 'cover']); expect(queue.getSnapshot().stopped).toBeNull();
  expect(queue.getSnapshot().files[slotId]).toMatchObject({ state: 'refused', code: 'content_changed' });
  expect(queue.getSnapshot().files[slotTwo]).toMatchObject({ state: 'failed', code: 'ADMIN_IMPORT_NOT_FOUND' });
  expect(queue.getSnapshot().files.cover).toMatchObject({ state: 'failed', code: 'ADMIN_IMPORT_ASSET_EXISTS' });
  expect(server.requests.filter(request => !request.slot)).toHaveLength(2);
});

test('a staged copy still being removed is refused without a request, and a receipt for another operation stays unknown', async () => {
  const item = project(); item.assets = [{ ...asset(slotId, 'cleanupFailed'), recovery: { operationId: original, expectedRevision: 2, kind: 'cleanup', startedByMe: true } }];
  const server = serve(item, () => ({ body: next => ({ item: next, receipt: { operationId: '40000000-0000-4000-8000-000000000004', kind: 'upload', revision: next.revision } }) }));
  const queue = importUploadQueue(item.id); queue.start(item, files(), adminWorkspace.capture()); await settle(queue);
  expect(server.requests.map(request => request.slot)).toEqual([slotTwo]);
  expect(queue.getSnapshot().files[slotId]).toEqual({ state: 'refused', code: 'cleanup_pending', operationId: null });
  expect(queue.getSnapshot().files[slotTwo].state).toBe('unknown');
});

test('Resume while uploading adds nothing, and an explicit retry joins the running queue once', async () => {
  const item = project(), gate = deferred<void>(), server = serve(item, (_seen, index) => index === 0 ? { hold: gate.promise } : undefined), queue = importUploadQueue(item.id), source = files();
  queue.start(item, { [slotId]: source[slotId] }, adminWorkspace.capture()); await vi.waitFor(() => expect(server.requests).toHaveLength(1));
  queue.start(item, source, adminWorkspace.capture()); expect(queue.getSnapshot().files[slotTwo]).toBeUndefined();
  queue.enqueue(slotId, source[slotId], item, adminWorkspace.capture());
  for (let attempt = 0; attempt < 2; attempt++) queue.enqueue(slotTwo, source[slotTwo], item, adminWorkspace.capture());
  expect(queue.getSnapshot().files[slotTwo].state).toBe('queued'); gate.resolve(); await settle(queue);
  expect(server.uploads().map(request => request.slot)).toEqual([slotId, slotTwo]); expect(server.max()).toBe(1);
  expect(Object.values(queue.getSnapshot().files).map(value => value.state)).toEqual(['ready', 'ready']);
});

test('a publication lock met while reconciling keeps that upload unknown and stops before any bytes are sent', async () => {
  const item = project(); item.assets = [asset(slotId, 'unknown')];
  const server = serve(item, seen => seen.reconcile ? { status: 409, code: 'ADMIN_IMPORT_PUBLICATION_LOCKED' } : undefined), queue = importUploadQueue(item.id);
  queue.start(item, files(), adminWorkspace.capture()); await settle(queue);
  expect(server.uploads()).toHaveLength(0); expect(queue.getSnapshot().stopped).toBe('publication');
  expect(queue.getSnapshot().files[slotId]).toMatchObject({ state: 'unknown', operationId: original }); expect(queue.getSnapshot().files[slotTwo].state).toBe('stopped');
});

test.each([
  ['switched-off imports', 'unavailable', () => adminWorkspace.authorize(captureAccountOperation(viewer), false, true)],
  ['a suspended capability check', 'permission', () => adminWorkspace.suspend()]
] as const)('%s mid-file stops the queue as %s after the current file', async (_name, reason, change) => {
  const item = project(), gate = deferred<void>(), server = serve(item, (_seen, index) => index === 0 ? { hold: gate.promise } : undefined), queue = importUploadQueue(item.id);
  queue.start(item, files(), adminWorkspace.capture()); await vi.waitFor(() => expect(server.requests).toHaveLength(1));
  change(); gate.resolve(); await settle(queue);
  expect(server.requests).toHaveLength(1); expect(queue.getSnapshot().stopped).toBe(reason);
  expect(queue.getSnapshot().files[slotId].state).toBe('ready'); expect(queue.getSnapshot().files[slotTwo].state).toBe('stopped');
});

test('reopening stops reconciling at a permission failure and never retries later uploads', async () => {
  const item = project(); item.assets = [asset(slotId, 'unknown'), asset(slotTwo, 'pending', true, '40000000-0000-4000-8000-000000000004')];
  const server = serve(item, () => ({ status: 403, code: 'ADMIN_IMPORT_ADMIN_REQUIRED' })), queue = importUploadQueue(item.id);
  await queue.reconcileOnOpen(item, adminWorkspace.capture());
  expect(server.requests).toHaveLength(1); expect(server.requests[0].reconcile).toBe(true); expect(adminWorkspace.getSnapshot().authorized).toBe(false);
});

test('a Resume during reopen reconciliation waits for it and then sends only the files still incomplete', async () => {
  const item = project(); item.assets = [asset(slotId, 'unknown')]; const gate = deferred<void>();
  const server = serve(item, (seen, index) => seen.reconcile && index === 0 ? { hold: gate.promise, state: 'ready' } : undefined), queue = importUploadQueue(item.id);
  const opening = queue.reconcileOnOpen(item, adminWorkspace.capture()); await vi.waitFor(() => expect(server.requests).toHaveLength(1));
  queue.start(item, files(), adminWorkspace.capture()); await new Promise(resolve => setTimeout(resolve, 10));
  expect(server.requests).toHaveLength(1); expect(queue.getSnapshot().running).toBe(true);
  gate.resolve(); await opening; await settle(queue);
  expect(server.requests.map(request => [request.slot, request.reconcile])).toEqual([[slotId, true], [slotTwo, false]]);
  expect(queue.getSnapshot().files[slotId]).toEqual({ state: 'ready', code: null, operationId: original }); expect(queue.getSnapshot().files[slotTwo].state).toBe('ready');
});
